];
----MODEL
/** Power classes from the build spec's content section. */
export const POWER_CLASSES = ['Aerial', 'Energy', 'Psionic', 'Tech', 'Mutant', 'Cosmic', 'Enhanced'] as const;
export type PowerClass = (typeof POWER_CLASSES)[number];

/** Roster status. Active, Injured, Reserve and MIA are the spec's four states. */
export const HERO_STATUSES = ['Active', 'Injured', 'Reserve', 'MIA'] as const;
export type HeroStatus = (typeof HERO_STATUSES)[number];

/** Threat clearance tiers, 1 (lowest) to 5 (highest). */
export const CLEARANCE_TIERS = ['Tier 1', 'Tier 2', 'Tier 3', 'Tier 4', 'Tier 5'] as const;
export type ClearanceTier = (typeof CLEARANCE_TIERS)[number];

export interface Hero {
  readonly id: string;
  readonly name: string;
  readonly alias: string;
  readonly powerClass: PowerClass;
  /** Power index, 0 to 100. */
  readonly powerIndex: number;
  readonly status: HeroStatus;
  readonly clearanceTier: ClearanceTier;
  readonly missionCount: number;
  /** Mission success rate, as a whole-number percentage (0 to 100). */
  readonly successRate: number;
  /** Free-text dossier notes, edited on the hero detail screen. */
  readonly notes: string;
}

/** The fields the edit form may change. Status, clearance and history are not edited here. */
export type HeroEdit = Pick<Hero, 'name' | 'alias' | 'powerClass' | 'powerIndex' | 'notes'>;
----SERVICE
import { Service, computed, signal } from '@angular/core';
import { EXAMPLE_ROSTER } from './hero.example-roster';
import type { Hero, HeroEdit } from './hero.model';

/**
 * Holds the hero roster as in-memory signal state. There is no backend: the roster
 * is EXAMPLE DATA and resets on every page load. Updates replace the hero record
 * in place, so any computed that reads the roster sees the change.
 */
@Service()
export class HeroService {
  private readonly heroes = signal<readonly Hero[]>(EXAMPLE_ROSTER);

  /** The full roster, in the order it was seeded. */
  readonly roster = this.heroes.asReadonly();

  /** Roster count, for stat tiles and the table footer. */
  readonly count = computed(() => this.heroes().length);

  /** Returns the hero with this id, or undefined if there is none. */
  findById(id: string): Hero | undefined {
    return this.heroes().find((hero) => hero.id === id);
  }

  /**
   * Applies the edit to the hero with this id and returns the updated record, or
   * undefined if no hero has that id. Status, clearance and mission history are
   * not touched here.
   */
  update(id: string, edit: HeroEdit): Hero | undefined {
    let updated: Hero | undefined;
    this.heroes.update((roster) =>
      roster.map((hero) => {
        if (hero.id !== id) return hero;
        updated = { ...hero, ...edit };
        return updated;
      }),
    );
    return updated;
  }
}
----DASH
import { computed, inject, Injectable } from '@angular/core';
import { Router } from '@angular/router';
import type { Hero } from '../domain/hero.model';
import { HeroService } from '../domain/hero.service';

/** How many hero cards the "top heroes this cycle" grid shows. */
const TOP_HERO_COUNT = 4;

/** Component-scoped ViewModel for the Operations Dashboard. All figures derive from the roster. */
@Injectable()
export class DashboardViewModel {
  private readonly _heroes = inject(HeroService);
  private readonly _router = inject(Router);

  /** Roster count, for the stat tile and the roster heading. */
  readonly heroCount = this._heroes.count;

  readonly missionsOnRecord = computed(() =>
    this._heroes.roster().reduce((total, hero) => total + hero.missionCount, 0),
  );

  /** Mean power index, rounded to a whole number. Zero for an empty roster. */
  readonly averagePower = computed(() => {
    const roster = this._heroes.roster();
    if (roster.length === 0) return 0;
    const sum = roster.reduce((total, hero) => total + hero.powerIndex, 0);
    return Math.round(sum / roster.length);
  });

  /** Heroes not on Active duty: Injured, Reserve or MIA. */
  readonly offDuty = computed(() => this._heroes.roster().filter((hero) => hero.status !== 'Active').length);

  /** Highest power index first. Ties keep roster order. */
  readonly topHeroes = computed<readonly Hero[]>(() =>
    [...this._heroes.roster()].sort((a, b) => b.powerIndex - a.powerIndex).slice(0, TOP_HERO_COUNT),
  );

  /** Opens the dossier for a hero. */
  openHero(hero: Hero): void {
    void this._router.navigate(['/detail', hero.id]);
  }
}
