import { Component, computed, input, output } from '@angular/core';
import { HlmAvatarImports } from '@spartan-ng/helm/avatar';
import { HlmBadge } from '@spartan-ng/helm/badge';
import { HlmButton } from '@spartan-ng/helm/button';
import { HlmCard, HlmCardContent, HlmCardDescription, HlmCardFooter, HlmCardHeader, HlmCardTitle } from '@spartan-ng/helm/card';
import type { Hero, HeroStatus } from '../../domain/hero.model';
import { PowerMeter } from '../power-meter/power-meter';

type StatusVariant = 'success' | 'warning' | 'destructive' | 'secondary';

/** Status to badge variant. Active is success, Injured is warning, MIA is destructive, Reserve is neutral. */
const STATUS_VARIANT: Readonly<Record<HeroStatus, StatusVariant>> = {
  Active: 'success',
  Injured: 'warning',
  Reserve: 'secondary',
  MIA: 'destructive',
};

// Presentational: the hero comes in as an input, the dossier request goes out as an output.
// Navigation is the ViewModel's job, so this component injects nothing.
@Component({
  selector: 'app-hero-card',
  imports: [
    HlmAvatarImports,
    HlmBadge,
    HlmButton,
    HlmCard,
    HlmCardContent,
    HlmCardDescription,
    HlmCardFooter,
    HlmCardHeader,
    HlmCardTitle,
    PowerMeter,
  ],
  templateUrl: './hero-card.html',
  styleUrl: './hero-card.css',
})
export class HeroCard {
  readonly hero = input.required<Hero>();
  readonly opened = output<Hero>();

  protected readonly statusVariant = computed(() => STATUS_VARIANT[this.hero().status]);

  /** Two-letter portrait initials from the first two words with letters, e.g. "Dr. Ion" gives "DI". */
  protected readonly initials = computed(() =>
    this.hero()
      .name.split(/\s+/)
      .filter((word) => /[A-Za-z]/.test(word))
      .slice(0, 2)
      .map((word) => word[0].toUpperCase())
      .join(''),
  );
}

