@reference "../../styles.css";

/* min-w-0 on each grid region lets it shrink below its content, so the wide table scrolls inside its own container, not the page. */
.roster { @apply grid min-w-0 content-start gap-6 p-6; }
.roster__header { @apply grid gap-1; }
.roster__filters { @apply flex flex-wrap items-end gap-3; }
.roster__search { @apply w-full sm:w-72; }
.roster__class { @apply w-full sm:w-48; }
.roster__recruit { @apply ms-auto; }
.roster__panel { @apply min-w-0; }
.roster__footer { @apply flex-wrap justify-between gap-2; }
.roster__num { @apply text-end; }
.roster__hero { @apply flex items-center gap-3; }
.roster__identity { @apply grid min-w-0; }
.roster__sr-only { @apply sr-only; }

